code:
p::before {
  content: "→ ";
  color: blue;
}

p::after {
  content: " ←";
  color: red;
}

/* <p>Hello</p> will visually show: → Hello ← */

li:nth-child(2) {
  color: red; /* selects the 2nd li */
}

li:nth-child(odd) {
  background: #f2f2f2; /* selects 1st, 3rd, 5th... */
}

li:nth-child(3n) {
  font-weight: bold; /* selects every 3rd li */
}

/* Style all buttons except the one with class 'disabled' */
button:not(.disabled) {
  background: green;
  cursor: pointer;
}

/* Style all list items except the last one */
li:not(:last-child) {
  border-bottom: 1px solid #ccc;
}
